import React, { useState, useEffect } from 'react';
import { X, Save, AlertCircle, Calendar, DollarSign, Wrench, Package, FileText, User, CheckCircle, Clock, AlertTriangle, ArrowRight } from 'lucide-react';
import { Reparation } from '../types';

interface ReparationFormProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: any) => void;
  reparation?: Reparation;
  materiels: any[];
  incidents: any[];
  incidentSource?: any;
  userName: string;
}

const ReparationForm: React.FC<ReparationFormProps> = ({
  isOpen,
  onClose,
  onSubmit,
  reparation,
  materiels,
  incidents,
  incidentSource,
  userName
}) => {
  const [formData, setFormData] = useState({
    materiel: '',
    incident: '',
    type_reparation: 'corrective',
    date_debut: '',
    date_fin: '',
    cout: '',
    description: '',
    technicien_responsable: ''
  });

  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [selectedMateriel, setSelectedMateriel] = useState<any>(null);
  const [selectedIncident, setSelectedIncident] = useState<any>(null);
  const [isEditingDateFin, setIsEditingDateFin] = useState(false);

  // Initialiser le formulaire
  useEffect(() => {
    if (!isOpen) return;

    const today = new Date().toISOString().split('T')[0];
    
    if (reparation) {
      // Mode édition
      const formatDateForInput = (dateString?: string) => {
        if (!dateString) return '';
        const date = new Date(dateString);
        return date.toISOString().split('T')[0];
      };

      setFormData({
        materiel: reparation.materiel?.toString() || '',
        incident: reparation.incident?.toString() || '',
        type_reparation: reparation.type_reparation || 'corrective',
        date_debut: formatDateForInput(reparation.date_debut),
        date_fin: reparation.date_fin ? formatDateForInput(reparation.date_fin) : '',
        cout: reparation.cout?.toString() || '',
        description: reparation.description || '',
        technicien_responsable: reparation.technicien_responsable || userName
      });

      setIsEditingDateFin(!!reparation.date_fin);

      // Trouver le matériel
      const materiel = materiels.find(m => 
        m.id === reparation.materiel || 
        m._id === reparation.materiel
      );
      setSelectedMateriel(materiel);

      // Trouver l'incident
      const incident = incidents.find(i => 
        i.id === reparation.incident || 
        i._id === reparation.incident
      );
      setSelectedIncident(incident);

    } else if (incidentSource) {
      // Mode création avec incident source
      console.log('🎯 Incident source reçu:', incidentSource);

      // Trouver l'incident complet dans la liste
      const incident = incidents.find(i => 
        i.id === incidentSource.id || 
        i._id === incidentSource.id ||
        i.id === incidentSource
      ) || incidentSource;

      setSelectedIncident(incident);

      // Trouver le matériel lié à l'incident
      let materielId = '';
      let materiel = null;

      // Essayer différentes façons de récupérer le matériel
      if (incident.materiel) {
        materielId = incident.materiel;
        materiel = materiels.find(m => m.id === materielId || m._id === materielId);
      } else if (incident.materiel_concerne) {
        materielId = incident.materiel_concerne;
        materiel = materiels.find(m => m.id === materielId || m._id === materielId);
      } else if (incident.materiel_details) {
        materiel = incident.materiel_details;
        materielId = materiel.id || materiel._id;
      }

      // Déterminer le type de réparation
      let typeReparation = 'corrective';
      if (materiel) {
        const etat = (materiel.etat || '').toLowerCase();
        if (etat.includes('panne') || etat.includes('hors') || etat.includes('defect')) {
          typeReparation = 'corrective';
        } else {
          typeReparation = 'preventive';
        }
      }

      // Description par défaut
      const description = incident.description 
        ? `Réparation suite à l'incident #${incident.id || incident._id}: ${incident.description.substring(0, 100)}${incident.description.length > 100 ? '...' : ''}`
        : '';

      setFormData({
        materiel: materielId.toString() || '',
        incident: (incident.id || incident._id || '').toString(),
        type_reparation: typeReparation,
        date_debut: today,
        date_fin: '',
        cout: '',
        description: description,
        technicien_responsable: userName
      });

      setSelectedMateriel(materiel);
      setIsEditingDateFin(false);

    } else {
      // Mode création normal
      setFormData({
        materiel: '',
        incident: '',
        type_reparation: 'corrective',
        date_debut: today,
        date_fin: '',
        cout: '',
        description: '',
        technicien_responsable: userName
      });
      setSelectedMateriel(null);
      setSelectedIncident(null);
      setIsEditingDateFin(false);
    }
  }, [isOpen, reparation, incidentSource, incidents, materiels, userName]);

  // Filtrer les incidents actifs
  const incidentsActifs = incidents.filter(incident => {
    const statut = (incident.statut || '').toLowerCase();
    return statut === 'ouvert' || statut === 'en_cours' || statut === 'en cours';
  });

  // Quand on change d'incident
  const handleIncidentChange = (incidentId: string) => {
    const incident = incidents.find(i => 
      i.id?.toString() === incidentId || 
      i._id?.toString() === incidentId
    );
    
    setSelectedIncident(incident);
    setFormData(prev => ({ ...prev, incident: incidentId }));
    
    // Trouver le matériel lié
    if (incident) {
      let materielId = '';
      let materiel = null;
      
      if (incident.materiel) {
        materielId = incident.materiel.toString();
        materiel = materiels.find(m => 
          m.id?.toString() === materielId || 
          m._id?.toString() === materielId
        );
      } else if (incident.materiel_concerne) {
        materielId = incident.materiel_concerne.toString();
        materiel = materiels.find(m => 
          m.id?.toString() === materielId || 
          m._id?.toString() === materielId
        );
      }
      
      if (materiel) {
        setFormData(prev => ({ 
          ...prev, 
          materiel: materielId 
        }));
        setSelectedMateriel(materiel);
      }
    }
  };

  // Quand on change de matériel
  const handleMaterielChange = (materielId: string) => {
    const materiel = materiels.find(m => 
      m.id?.toString() === materielId || 
      m._id?.toString() === materielId
    );
    setSelectedMateriel(materiel);
    setFormData(prev => ({ ...prev, materiel: materielId }));
  };

  // Gestion des changements simples
  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  // Toggle date de fin
  const toggleDateFin = () => {
    if (isEditingDateFin) {
      setIsEditingDateFin(false);
      setFormData(prev => ({ ...prev, date_fin: '' }));
    } else {
      setIsEditingDateFin(true);
      if (!formData.date_fin) {
        const today = new Date().toISOString().split('T')[0];
        setFormData(prev => ({ ...prev, date_fin: today }));
      }
    }
  };

  // DÉTERMINER L'ÉTAT APRÈS RÉPARATION - SIMPLIFIÉ
  const getEtatApresReparation = () => {
    if (!isEditingDateFin) {
      // Réparation en cours
      switch(formData.type_reparation) {
        case 'corrective':
          return { etat: 'en_reparation', label: 'En réparation', badge: 'badge-warning' };
        case 'preventive':
          return { etat: 'en_maintenance', label: 'En maintenance', badge: 'badge-info' };
        case 'ameliorative':
          return { etat: 'en_amelioration', label: 'En amélioration', badge: 'badge-primary' };
        default:
          return { etat: 'en_reparation', label: 'En réparation', badge: 'badge-warning' };
      }
    } else {
      // Réparation terminée
      switch(formData.type_reparation) {
        case 'corrective':
          return { etat: 'repare', label: 'Réparé', badge: 'badge-success' };
        case 'preventive':
          return { etat: 'fonctionnel', label: 'Fonctionnel', badge: 'badge-success' };
        case 'ameliorative':
          return { etat: 'ameliore', label: 'Amélioré', badge: 'badge-success' };
        default:
          return { etat: 'fonctionnel', label: 'Fonctionnel', badge: 'badge-success' };
      }
    }
  };

  // Validation
  const validateForm = () => {
    const newErrors: Record<string, string> = {};

    if (!formData.materiel) {
      newErrors.materiel = 'Le matériel est requis';
    }
    if (!formData.type_reparation) {
      newErrors.type_reparation = 'Le type de réparation est requis';
    }
    if (!formData.date_debut) {
      newErrors.date_debut = 'La date de début est requise';
    }
    if (!formData.technicien_responsable) {
      newErrors.technicien_responsable = 'Le technicien est requis';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  // Soumission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!validateForm()) {
      return;
    }

    setIsSubmitting(true);

    try {
      const etatApres = getEtatApresReparation();
      
      // Préparer les données SIMPLES
      const data = {
        materiel: parseInt(formData.materiel) || formData.materiel,
        incident: formData.incident ? (parseInt(formData.incident) || formData.incident) : null,
        type_reparation: formData.type_reparation,
        date_debut: formData.date_debut,
        date_fin: isEditingDateFin && formData.date_fin ? formData.date_fin : null,
        cout: formData.cout ? parseFloat(formData.cout) : 0,
        technicien_responsable: formData.technicien_responsable,
        description: formData.description,
        
        // Ajouter les infos pour la mise à jour du matériel
        update_materiel_etat: true,
        nouveau_etat: etatApres.etat,
        materiel_id: formData.materiel
      };

      console.log('📤 Données envoyées:', data);
      await onSubmit(data);

    } catch (error) {
      console.error('Erreur:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  // Obtenir le nom d'un matériel
  const getMaterielName = (materielId: string) => {
    if (!materielId) return 'Non sélectionné';
    const materiel = materiels.find(m => 
      m.id?.toString() === materielId || 
      m._id?.toString() === materielId
    );
    return materiel?.nom || materiel?.name || `Matériel #${materielId}`;
  };

  // Obtenir l'icône d'état
  const getEtatIcon = (etat: string) => {
    const etatLower = (etat || '').toLowerCase();
    if (etatLower.includes('panne')) return <AlertTriangle className="h-4 w-4" />;
    if (etatLower.includes('repar')) return <Wrench className="h-4 w-4" />;
    if (etatLower.includes('fonction')) return <CheckCircle className="h-4 w-4" />;
    if (etatLower.includes('maintenance')) return <Clock className="h-4 w-4" />;
    return <Package className="h-4 w-4" />;
  };

  if (!isOpen) return null;

  const etatApres = getEtatApresReparation();
  const etatActuel = selectedMateriel?.etat || 'inconnu';

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto">
      <div className="fixed inset-0 bg-black/50" onClick={onClose} />
      
      <div className="flex min-h-screen items-center justify-center p-4">
        <div className="relative w-full max-w-4xl bg-base-100 rounded-lg shadow-xl">
          {/* En-tête */}
          <div className="flex items-center justify-between p-6 border-b">
            <div className="flex items-center gap-3">
              <Wrench className="h-6 w-6 text-primary" />
              <div>
                <h2 className="text-xl font-bold">
                  {reparation ? 'Modifier la réparation' : 'Nouvelle réparation'}
                </h2>
                <p className="text-sm opacity-60">
                  {incidentSource ? `Pour l'incident #${incidentSource.id || incidentSource}` : 'Créez une nouvelle réparation'}
                </p>
              </div>
            </div>
            <button onClick={onClose} className="btn btn-ghost btn-sm">
              <X className="h-5 w-5" />
            </button>
          </div>

          <form onSubmit={handleSubmit}>
            <div className="p-6 space-y-6">
              {/* Message d'info */}
              {incidentSource && !reparation && (
                <div className="alert alert-info">
                  <ArrowRight className="h-4 w-4" />
                  <span>Réparation pour l'incident #{incidentSource.id || incidentSource}</span>
                </div>
              )}

              {/* Sélection d'incident */}
              <div className="form-control">
                <label className="label">
                  <span className="label-text font-semibold flex items-center gap-2">
                    <FileText className="h-4 w-4" />
                    Incident concerné
                  </span>
                </label>
                <select
                  value={formData.incident}
                  onChange={(e) => handleIncidentChange(e.target.value)}
                  className="select select-bordered"
                  disabled={!!incidentSource && !reparation}
                >
                  <option value="">Sélectionnez un incident</option>
                  {incidentsActifs.map(incident => (
                    <option key={incident.id || incident._id} value={incident.id || incident._id}>
                      #{incident.id || incident._id} - {incident.description?.substring(0, 50) || 'Incident'}
                    </option>
                  ))}
                </select>
              </div>

              {/* Matériel (auto-rempli) */}
              <div className="form-control">
                <label className="label">
                  <span className="label-text font-semibold flex items-center gap-2">
                    <Package className="h-4 w-4" />
                    Matériel concerné
                  </span>
                </label>
                
                {selectedMateriel ? (
                  <div className="p-4 bg-base-200 rounded-lg">
                    <div className="flex justify-between items-center">
                      <div>
                        <div className="font-bold">{selectedMateriel.nom || selectedMateriel.name}</div>
                        <div className="text-sm opacity-70">
                          Réf: {selectedMateriel.reference || 'N/A'} | 
                          État: <span className="badge badge-sm ml-1">{selectedMateriel.etat || 'inconnu'}</span>
                        </div>
                      </div>
                      <button
                        type="button"
                        onClick={() => {
                          setSelectedMateriel(null);
                          setFormData(prev => ({ ...prev, materiel: '' }));
                        }}
                        className="btn btn-ghost btn-xs"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </div>
                  </div>
                ) : (
                  <select
                    value={formData.materiel}
                    onChange={(e) => handleMaterielChange(e.target.value)}
                    className="select select-bordered"
                  >
                    <option value="">Sélectionnez un matériel</option>
                    {materiels.map(materiel => (
                      <option key={materiel.id || materiel._id} value={materiel.id || materiel._id}>
                        {materiel.nom || materiel.name} - {materiel.etat || 'inconnu'}
                      </option>
                    ))}
                  </select>
                )}
              </div>

              {/* Type de réparation */}
              <div className="form-control">
                <label className="label">
                  <span className="label-text font-semibold">Type de réparation</span>
                </label>
                <div className="flex gap-2">
                  {['corrective', 'preventive', 'ameliorative'].map(type => (
                    <button
                      key={type}
                      type="button"
                      onClick={() => setFormData(prev => ({ ...prev, type_reparation: type }))}
                      className={`btn btn-sm flex-1 ${formData.type_reparation === type ? 'btn-primary' : 'btn-outline'}`}
                    >
                      {type === 'corrective' ? 'Corrective' : 
                       type === 'preventive' ? 'Préventive' : 'Améliorative'}
                    </button>
                  ))}
                </div>
              </div>

              {/* Dates */}
              <div className="grid grid-cols-2 gap-4">
                <div className="form-control">
                  <label className="label">
                    <span className="label-text font-semibold">Date début</span>
                  </label>
                  <input
                    type="date"
                    name="date_debut"
                    value={formData.date_debut}
                    onChange={handleChange}
                    className="input input-bordered"
                    required
                  />
                </div>
                
                <div className="form-control">
                  <label className="label">
                    <span className="label-text font-semibold">Date fin (optionnel)</span>
                  </label>
                  <div className="flex gap-2">
                    <input
                      type="date"
                      name="date_fin"
                      value={formData.date_fin}
                      onChange={handleChange}
                      className="input input-bordered flex-1"
                      disabled={!isEditingDateFin}
                    />
                    <button
                      type="button"
                      onClick={toggleDateFin}
                      className={`btn ${isEditingDateFin ? 'btn-primary' : 'btn-outline'}`}
                    >
                      {isEditingDateFin ? '✓' : 'Ajouter'}
                    </button>
                  </div>
                </div>
              </div>

              {/* Coût et Technicien */}
              <div className="grid grid-cols-2 gap-4">
                <div className="form-control">
                  <label className="label">
                    <span className="label-text font-semibold">Coût (Ar)</span>
                  </label>
                  <input
                    type="number"
                    name="cout"
                    value={formData.cout}
                    onChange={handleChange}
                    className="input input-bordered"
                    placeholder="0"
                    min="0"
                  />
                </div>
                
                <div className="form-control">
                  <label className="label">
                    <span className="label-text font-semibold">Technicien</span>
                  </label>
                  <input
                    type="text"
                    name="technicien_responsable"
                    value={formData.technicien_responsable}
                    onChange={handleChange}
                    className="input input-bordered"
                    placeholder="Nom du technicien"
                    required
                  />
                </div>
              </div>

              {/* Description */}
              <div className="form-control">
                <label className="label">
                  <span className="label-text font-semibold">Description</span>
                </label>
                <textarea
                  name="description"
                  value={formData.description}
                  onChange={handleChange}
                  className="textarea textarea-bordered h-32"
                  placeholder="Description des travaux effectués..."
                />
              </div>

              {/* Impact sur le matériel */}
              {formData.materiel && (
                <div className="p-4 bg-base-200 rounded-lg">
                  <h3 className="font-bold mb-2">Impact sur le matériel</h3>
                  <div className="flex items-center justify-between">
                    <div className="text-center">
                      <div className="badge badge-lg">
                        {getEtatIcon(etatActuel)}
                        <span className="ml-2">{etatActuel}</span>
                      </div>
                      <div className="text-xs mt-1">État actuel</div>
                    </div>
                    
                    <ArrowRight className="h-6 w-6" />
                    
                    <div className="text-center">
                      <div className={`badge badge-lg ${etatApres.badge}`}>
                        {getEtatIcon(etatApres.etat)}
                        <span className="ml-2">{etatApres.label}</span>
                      </div>
                      <div className="text-xs mt-1">
                        {isEditingDateFin ? 'État après réparation' : 'État pendant réparation'}
                      </div>
                    </div>
                  </div>
                  <div className="text-sm mt-4 text-center">
                    {isEditingDateFin 
                      ? 'Le matériel sera marqué comme ' + etatApres.label.toLowerCase()
                      : 'Le matériel sera en ' + etatApres.label.toLowerCase() + ' pendant la réparation'
                    }
                  </div>
                </div>
              )}

              {/* Erreurs */}
              {Object.keys(errors).length > 0 && (
                <div className="alert alert-error">
                  <AlertCircle className="h-4 w-4" />
                  <div>
                    {Object.entries(errors).map(([field, message]) => (
                      <div key={field}>{message}</div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            {/* Actions */}
            <div className="flex justify-end gap-2 p-6 border-t">
              <button
                type="button"
                onClick={onClose}
                className="btn btn-outline"
                disabled={isSubmitting}
              >
                Annuler
              </button>
              <button
                type="submit"
                className="btn btn-primary gap-2"
                disabled={isSubmitting}
              >
                {isSubmitting ? (
                  <>
                    <span className="loading loading-spinner loading-sm"></span>
                    Enregistrement...
                  </>
                ) : (
                  <>
                    <Save className="h-4 w-4" />
                    {reparation ? 'Mettre à jour' : 'Créer'}
                  </>
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default ReparationForm;